function modelThink(m){
  var a=mount(m,'mk-think-clock'),b=mount(m,'mk-think-ans');
  OAOKit.clock(a,{key:'g4-4-10-05-ok-think',rounds:[
    {name:'Time A: 2 h 10 min',rate:60,big:HR,small:MIN,target:130,show:'turns',steps:[1,5],
     text:'Wind <b>Time A: 2 h 10 min</b>: the minute hand goes 2 full turns, then 10 more minutes. Or work it out your own way.',doneText:'That is Time A. Now try Time B.'},
    {name:'Time B: 125 min',rate:60,big:HR,small:MIN,target:125,show:'count',steps:[1,5],
     text:'Wind <b>Time B: 125 min</b>. Watch for each full turn. Or work it out your own way.',doneText:'That is Time B. Compare the two.'}]});
  var st=ls('g4-4-10-05-think-ans',null)||{a:['',''],ok:false};
  b.innerHTML='<form class="bm-form mk-two"><label class="mk-two-q" for="thinkWho">Which time is longer, A or B?</label><input id="thinkWho" type="text" autocomplete="off" aria-label="Which time is longer" value="'+esc(st.a[0])+'" style="width:5em">'+
    '<label class="mk-two-q" for="thinkBy">By how many minutes?</label><input id="thinkBy" type="text" inputmode="numeric" autocomplete="off" aria-label="By how many minutes" value="'+esc(st.a[1])+'"><span class="bm-u">min</span><button type="submit" class="ok-btn">Check</button></form><div class="ok-msg" aria-live="polite"></div>';
  var f=b.querySelector('form'),msg=b.querySelector('.ok-msg');
  function say(t,k){msg.className='ok-msg'+(k?' '+k:'');msg.textContent=t;}
  var DONE='Yes! Time A is longer, by 5 minutes. On the Learn tab, the Math Crew shows two ways to find it. Did one match yours?';
  if(st.ok){say(DONE,'good');[].forEach.call(f.querySelectorAll('input'),function(x){x.disabled=true;});}
  f.onsubmit=function(e){e.preventDefault();var who=f.thinkWho.value.trim().toLowerCase(),by=num(f.thinkBy.value);st.a=[f.thinkWho.value,f.thinkBy.value];lsSet('g4-4-10-05-think-ans',st);
    if(!who||by==null)return say('Type A or B, and a number of minutes.','hint');
    var isA=/^(time )?a$/.test(who),isB=/^(time )?b$/.test(who);
    if(isA&&by===5){st.ok=true;lsSet('g4-4-10-05-think-ans',st);OAOKit._snd.done();say(DONE,'good');[].forEach.call(f.querySelectorAll('input'),function(x){x.disabled=true;});earn('think',4,4,b,'You tried it first!');return;}
    OAOKit._snd.no();
    if(isA&&by===85)return say('Is 2 h 10 min the same as 210 minutes? Wind it on the clock: each full turn is one hour, and an hour isn\'t 100 minutes.','hint');
    if(isB)return say('Wind both times on the clock. Which one went farther past 2 full turns?','hint');
    if(isA)return say('Time A is longer, yes! Now count: how many more minutes past 2 full turns?','hint');
    say('Wind both times on the clock, or write them the same way, then compare.','hint');};
}
